426	    /**
427	     Consumes an attribute key off the queue, up to (but not including) whitespace or a comparison operator. CSS
428	     escapes in the key are decoded.
429	     */
430	    private String consumeAttributeKey(TokenQueue cq) {
431	        StringBuilder sb = StringUtil.borrowBuilder();
432	        OUT: while (!cq.isEmpty()) {
433	            if (cq.matchesWhitespace()) break;
434	            for (String eval : AttributeEvals) {
435	                if (cq.matches(eval)) break OUT;
436	            }
437	            if (cq.matches('\\')) cq.consumeCssEscapeSequence(sb);
438	            else sb.append(cq.consume());
439	        }
440	        return StringUtil.releaseBuilder(sb);
441	    }
442	
443	    /**
444	     Consumes an attribute value off the queue: either a quoted string (returned with its quotes, for decoding in the
445	     evaluator), or a bare value running to the next whitespace or the end of the queue.
446	     */
447	    private String consumeAttributeValue(TokenQueue cq) {
448	        if (cq.isEmpty()) return "";
449	
450	        if (cq.matches('"') || cq.matches('\'')) {
451	            StringBuilder sb = StringUtil.borrowBuilder();
452	            char quote = cq.consume();
453	            sb.append(quote);
454	            boolean closed = false;
455	            while (!cq.isEmpty()) {
456	                char c = cq.consume();
457	                sb.append(c);
458	                if (c == '\\' && !cq.isEmpty()) {
459	                    sb.append(cq.consume()); // keep the escaped character with its escape, for balanced decoding
460	                } else if (c == quote) {
461	                    closed = true;
462	                    break;
463	                }
464	            }
465	            if (!closed) {
466	                StringUtil.releaseBuilderVoid(sb);
467	                throw new Selector.SelectorParseException("Quoted value must have content");
468	            }
469	            return StringUtil.releaseBuilder(sb);
470	        }
471	
472	        // bare value, up to the next whitespace or the end of the queue
473	        StringBuilder sb = StringUtil.borrowBuilder();
474	        while (!cq.isEmpty() && !cq.matchesWhitespace()) sb.append(cq.consume());
475	        return StringUtil.releaseBuilder(sb);
476	    }
