638	    public static abstract class CssNthEvaluator extends Evaluator {
639	        /** Step */
640	        protected final int a;
641	        /** Offset */
642	        protected final int b;
643	
644	        public CssNthEvaluator(int step, int offset) {
645	            this.a = step;
646	            this.b = offset;
