662	        /**
663	         Tests if a 1-based sibling position matches the An+B periodic formula.
664	         @param a the step
665	         @param b the offset
666	         @param pos the 1-based position
667	         @return true if it matches
668	         */
669	        static boolean matchesNth(int a, int b, int pos) {
670	            if (a == 0) return pos == b;
671	            return (pos - b) * a >= 0 && (pos - b) % a == 0;
672	        }
673	
674	        @Override
675	        public String toString() {
676	            String format =
677	                (a == 0) ? ":%s(%3$d)"    // only offset (b)
678	                : (b == 0) ? ":%s(%2$dn)" // only step (a)
679	                : ":%s(%2$dn%3$+d)";      // step, offset
680	            return String.format(format, getPseudoClass(), a, b);
681	        }
