import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Selector;

public class LangCheck {
    static String html = "<main lang='en'><p id=a></p><div id=b lang='en-US'><span id=c></span></div><i id=d lang='ENough'></i><section id=e lang=''><b id=f></b></section></main>";
    static Document doc = Jsoup.parse(html);

    static void ids(String css, String expected) {
        String got = String.join(",", doc.select(css).stream().map(e -> e.id().isEmpty() ? e.tagName() : e.id()).toArray(String[]::new));
        System.out.println((got.equals(expected) ? "PASS " : "FAIL ") + css + " -> [" + got + "] expected [" + expected + "]");
    }

    static void fails(String css) {
        // run a legal query first to capture the original doc state
        String before = doc.select("*").outerHtml().hashCode() + "";
        try { doc.select(css); System.out.println("FAIL " + css + " did not throw"); }
        catch (Selector.SelectorParseException e) {
            String after = doc.select("*").outerHtml().hashCode() + "";
            System.out.println((before.equals(after) ? "PASS " : "FAIL ") + css + " threw; doc unchanged=" + before.equals(after));
        }
    }

    public static void main(String[] args) {
        ids(":lang(en)", "html,head,body,main,a,b,c"); // html/head/body inherit from... wait main is inside body
        // Actually <main> is inside body; html/head/body have no lang. So expected main,a,b,c only.
        ids(":lang(en-US)", "b,c");
        ids(":lang(enough)", "d");
        ids("main :not(:lang(en-US))", "a,d,e,f"); // descendants of main not en-US lang... spec says compound excluding en-US keeps main,a -> check variant
        ids(":not(:lang(en-US)):lang(en)", "main,a");
        // :has descendant language condition still matches main
        ids("main:has(:lang(en-US))", "main");
        // nesting in not/has/is with tags/attrs
        ids("p[id]:lang(en)", "a");
        ids("div:lang(en) > span", "c");
        ids(":is(p, span):lang(en-US)", "c");
        ids(":lang(EN)", "main,a,b,c"); // case-insensitive R
        ids(":lang( 'en' )", "main,a,b,c"); // quoted + outer whitespace
        ids(":lang(\"en-US\")", "b,c");
        // f must not inherit through empty lang on section; e/f don't match
        ids("section:lang(en)", "");
        ids("b:lang(en)", "");
        // whitespace inside, empty, comma lists, trailing junk, unclosed quote/paren
        fails(":lang(en us)");
        fails(":lang()");
        fails(":lang( )");
        fails(":lang(en,en-US)");
        fails(":lang(en)x");
        fails(":lang(");
        fails(":lang('en)");
        fails(":lang(en-US");
        // legal query after failures still works
        ids(":lang(en)", "main,a,b,c");
    }
}
