    Document doc = Jsoup.parse("<div lang='zh-Hant-HK'><p id=1><span id=2></span></p><i id=3 lang='zh'></i></div>");
    assertSelectedIds(doc.select(":lang(zh)"), "1", "2", "3", ""); // the div itself has no id
    assertEquals("div", doc.select(":lang(zh)").last().parent() == null ? "" : doc.select(":lang(zh-Hant)").get(2).tagName());
    assertSelectedIds(doc.select("p:lang(zh-Hant)"), "1");
    assertSelectedIds(doc.select("span:lang(zh-hant-hk)"), "2");
    assertSelectedIds(doc.select(":lang(zh-HK)"), "1", "2");
}

